LINE = re.compile(r'^\S+ \S+ \S+ \[[^\]]+\] "[^"]*" (\d{3}) \S+')


def status_counts(lines):
    counts = {}
    for line in lines:
        m = LINE.match(line)
        if m:
            code = int(m.group(1))
            counts[code] = counts.get(code, 0) + 1
    return counts

